"""Accept an actual bounded compile failure without inventing QA or GPU timings."""
import argparse,json
from pathlib import Path
from kernel_agent.registry import atomic_json
from experiments.full_delivery.formal_study import ROOT,verify,sha
from experiments.full_delivery.formal_results import store


def build_failure(root,folder,evidence):
    verify(root);proposal=json.loads((folder/'proposal.json').read_text());execution=json.loads((evidence/'execution.json').read_text());assert all((evidence/'remote'/n).stat().st_size==m['bytes'] and sha(evidence/'remote'/n)==m['sha256'] for n,m in execution['manifest'].items());run=evidence/'remote/run';state=json.loads((run/'run.json').read_text());work=run/'evaluation';job=work/'build';record=json.loads((job/'record.json').read_text());source=job/'source/kernels/gemm/wmma_sm86.cu';assert sha(source)==proposal['source_change']['source_sha256']==state['source_sha256'] and state['candidate_id']==proposal['descriptor']['id'];assert state['status']=='FAILED' and state['reason']=='pair candidate build failed; raw record retained';assert not (work/'result.json').exists() and not (job/'artifacts/nka_gemm_v1.so').exists() and len(list(work.glob('*/record.json')))==1
    command=record['command'];assert '--gpus' not in command and '--env' in command and 'NVIDIA_VISIBLE_DEVICES=void' in command and command[command.index('--user')+1]=='65534:65534' and '--network=none' in command and '--read-only' in command and '--cap-drop=ALL' in command and '--security-opt=no-new-privileges' in command;assert record['exit']!=0 and record['reason'] is None and record['status']=='REJECT' and record['source_unchanged'] and record['deps_unchanged'] and record['cleanup']['removed'];assert all(sha(job/'source'/n)==h for n,h in record['source_hashes'].items());raw=(job/'capture/stderr.bin').read_text(errors='replace');assert 'error:' in raw or 'error #' in raw;classification='type' if 'undefined' in raw or 'not declared' in raw else 'other'
    verification={'status':'PASS','scope':'CPU lossless archive/source hashes and no-GPU bounded builder failure receipt audit; no successful binary, QA, sanitizer or Event evidence','candidate_id':proposal['descriptor']['id'],'source_sha256':sha(source),'compile_status':'FAIL','compile_error':classification,'correctness':'NOT_RUN','gpu_execution_performed':False,'qa_checks':0,'raw_segments':0,'build_wall_seconds':record['wall_seconds'],'raw_files_verified':len(execution['manifest']),'new_model_calls':0,'production_release':False};atomic_json(evidence/'build-failure-verification.json',verification);entry={'descriptor':proposal['descriptor'],'verdict':'REJECT','reason':'compile_failed','compile_status':'FAIL','compile_error':classification,'correctness':'NOT_RUN','latencies':{},'proofs':{str(p.relative_to(ROOT)):sha(p) for p in [evidence/'build-failure-verification.json',run/'run.json',job/'record.json']},'evaluation_wall_seconds':record['wall_seconds'],'build_wall_seconds':record['wall_seconds'],'gpu_execution_performed':False};outcome=store(root,folder,entry);decision=json.loads((folder/'decision.json').read_text());decision.update(marginal_gpu_work=False,marginal_build_work=True,gpu_execution_performed=False);atomic_json(folder/'decision.json',decision);return verification


if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);p.add_argument('--folder',type=Path,required=True);p.add_argument('--evidence',type=Path,required=True);a=p.parse_args();print(json.dumps(build_failure(a.root.resolve(),a.folder.resolve(),a.evidence.resolve())))
